#!/usr/bin/env bash
# Documentation : brouillons, avatars posés par leur titulaire, cloche collaborative ; plages recalées.
# Prérequis : apply-fix-brouillons.sh et apply-docs-contenu.sh. Aucune migration.
# Usage (racine du repo) : bash apply-docs-brouillons.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/contenu/le-recensement-des-fichiers.mdx" 2>/dev/null | grep -qF "isPubliclyPlaced"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "isPubliclyPlaced" "apps/web/src/app/api/media/public/r2/[...path]/route.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-brouillons.sh"; exit 1; }
grep -qF "Un contenu fait de blocs" "apps/web/content/docs/dev/contenu/un-contenu-fait-de-blocs.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-contenu.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/api/fabriquer-une-procedure.mdx" "apps/web/content/docs/dev/api/gerer-les-erreurs.mdx" "apps/web/content/docs/dev/api/le-routeur-metier.mdx" "apps/web/content/docs/dev/api/maitriser-la-sortie.mdx" "apps/web/content/docs/dev/api/proteger-une-procedure.mdx" "apps/web/content/docs/dev/api/valider-l-entree.mdx" "apps/web/content/docs/dev/auth/la-session-dans-le-backend.mdx" "apps/web/content/docs/dev/contenu/le-recensement-des-fichiers.mdx" "apps/web/content/docs/dev/contenu/le-rendu-serveur.mdx" "apps/web/content/docs/dev/contenu/le-texte-riche.mdx" "apps/web/content/docs/dev/contenu/un-contenu-ecrit-par-un-membre.mdx" "apps/web/content/docs/dev/domaine/ce-que-voit-le-visiteur.mdx" "apps/web/content/docs/dev/domaine/les-conventions.mdx" "apps/web/content/docs/dev/domaine/un-modele-qui-s-ouvre.mdx" "apps/web/content/docs/dev/membres/documents-des-membres.mdx" "apps/web/content/docs/dev/membres/profil-et-premiere-connexion.mdx" "apps/web/content/docs/dev/stockage/servir-un-fichier.mdx")
EXPECT=("5de75f4af467:apps/web/content/docs/dev/api/fabriquer-une-procedure.mdx" "ee155c87a2bc:apps/web/content/docs/dev/api/gerer-les-erreurs.mdx" "2a6cfa9ab91c:apps/web/content/docs/dev/api/le-routeur-metier.mdx" "1b12d2d816d7:apps/web/content/docs/dev/api/maitriser-la-sortie.mdx" "319bfca48c94:apps/web/content/docs/dev/api/proteger-une-procedure.mdx" "a79dfd519fa3:apps/web/content/docs/dev/api/valider-l-entree.mdx" "047a5762bf32:apps/web/content/docs/dev/auth/la-session-dans-le-backend.mdx" "1036b69c1cc3:apps/web/content/docs/dev/contenu/le-recensement-des-fichiers.mdx" "de1c93be97d8:apps/web/content/docs/dev/contenu/le-rendu-serveur.mdx" "d66e30d40b20:apps/web/content/docs/dev/contenu/le-texte-riche.mdx" "3d6f87f9f948:apps/web/content/docs/dev/contenu/un-contenu-ecrit-par-un-membre.mdx" "ada7358e7424:apps/web/content/docs/dev/domaine/ce-que-voit-le-visiteur.mdx" "e9926068fbdc:apps/web/content/docs/dev/domaine/les-conventions.mdx" "b8119ad850a7:apps/web/content/docs/dev/domaine/un-modele-qui-s-ouvre.mdx" "3ecc58ce9288:apps/web/content/docs/dev/membres/documents-des-membres.mdx" "e1787d8ccc76:apps/web/content/docs/dev/membres/profil-et-premiere-connexion.mdx" "3db63b3a5e0e:apps/web/content/docs/dev/stockage/servir-un-fichier.mdx")
DIFF=0; for e in "${EXPECT[@]}"; do h=${e%%:*}; f=${e#*:}; c=$(git rev-parse "HEAD:$f" 2>/dev/null | cut -c1-12); if [ "$c" != "$h" ]; then [ $DIFF = 0 ] && echo "❌ ces fichiers ne sont pas dans l'état attendu (rien n'a été touché) :"; echo "   $f"; DIFF=1; fi; done; [ $DIFF = 0 ] || exit 1
CREATED=()
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "isPubliclyPlaced" "apps/web/content/docs/dev/contenu/le-recensement-des-fichiers.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR


python3 - <<'PY'
import base64
spec_skip_done = False
def sub(path, old, new):
    old, new = base64.b64decode(old).decode(), base64.b64decode(new).decode()
    s = open(path, encoding="utf-8").read()
    if s.count(old) == 0 and s.count(new) == 1 and spec_skip_done: return  # déjà fait par un script précédent
    assert s.count(old) == 1, (path, old[:80], s.count(old))
    open(path, "w", encoding="utf-8").write(s.replace(old, new))
