trap - ERR

[ "${AKFC_APPLY_ONLY:-0}" = "1" ] && { echo "Appliqué (sans vérification ni commit)."; exit 0; }
echo "== pnpm check =="
if pgrep -f "next dev" >/dev/null 2>&1; then
  echo "  (pnpm dev tourne : vérification sans effacer .next)"
  CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && pnpm --filter backend typecheck && pnpm typecheck && pnpm lint"
else
  CHECK="pnpm check"
fi
if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"
  grep -nE "error TS|✗ tutos|ERR_|Error:|EACCES|Permission denied" /tmp/akfc_tc.log | head -12
  echo "  … fin du journal :"; grep -v '^[[:space:]]*$' /tmp/akfc_tc.log | tail -15
  restore; exit 1
fi
echo "  ✅ check OK"
git add -- "${MODIFIED[@]}" "${CREATED[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
docs: brouillons, avatars posés par leur titulaire, cloche collaborative

- Contenu éditorial : audience d'un rendu et aperçu d'un brouillon (le rendu serveur), la garde
  de la route publique et isPubliclyPlaced (le recensement), assertOwnAvatars pour tout contenu
  (un contenu écrit par un membre)
- Stockage : la route publique ne sert que les fichiers d'un contenu publié (la limite connue est levée)
- Domaine : un brouillon reste visible des administrateurs ; extraits recalés
- Membres : erreurs d'avatar, conditions de visibilité des documents
- Plages de lignes recalées (API, authentification, domaine, stockage)

